// --- gather data ---
const anchor = element.querySelector('a[href*="/pin/"]');
if (!anchor) return;

const description = anchor.getAttribute('aria-label') || '';
const href = anchor.getAttribute('href') || '';

// Extract username from URL: /pin/<id>/ → look for user in referrer path
// Pinterest pin URLs are /pin/<id>/ — no username in that URL.
// Username may be in a profile link; try to find it in a sibling or parent board reference.
// Fallback: parse from data attribute or show "Pinterest"
const pinId = (href.match(/\/pin\/(\d+)/) || [])[1] || '';

// Try to get the image alt text (may be more descriptive than aria-label)
const img = element.querySelector('img[alt]');
const altText = img ? img.getAttribute('alt') : '';

// Prefer alt text if longer/different from aria-label
const displayText = (altText && altText.length > 0) ? altText : description;

// --- find or create the info bar ---
const BAR_CLASS = 'ext-pin-info-bar';
let bar = element.querySelector('.' + BAR_CLASS);
if (!bar) {
  bar = document.createElement('div');
  bar.className = BAR_CLASS;
  bar.style.cssText = [
    'display: block',
    'width: 100%',
    'box-sizing: border-box',
    'padding: 8px 10px 10px 10px',
    'background: #fff',
    'border-top: 1px solid #e9e9e9',
    'border-radius: 0 0 16px 16px',
    'font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    'pointer-events: none',
    'z-index: 1',
    'position: relative',
  ].join('; ');
  element.appendChild(bar);
}

// --- title (first ~6 words of description capitalised as a heading) ---
const titleEl_CLASS = 'ext-pin-info-title';
const descEl_CLASS  = 'ext-pin-info-desc';
const metaEl_CLASS  = 'ext-pin-info-meta';

let titleEl = bar.querySelector('.' + titleEl_CLASS);
if (!titleEl) {
  titleEl = document.createElement('div');
  titleEl.className = titleEl_CLASS;
  titleEl.style.cssText = [
    'font-size: 13px',
    'font-weight: 700',
    'color: #111',
    'line-height: 1.4',
    'margin-bottom: 3px',
    'overflow: hidden',
    'text-overflow: ellipsis',
    'white-space: nowrap',
    'max-width: 100%',
  ].join('; ');
  bar.appendChild(titleEl);
}

let descEl = bar.querySelector('.' + descEl_CLASS);
if (!descEl) {
  descEl = document.createElement('div');
  descEl.className = descEl_CLASS;
  descEl.style.cssText = [
    'font-size: 12px',
    'font-weight: 400',
    'color: #444',
    'line-height: 1.4',
    'display: -webkit-box',
    '-webkit-line-clamp: 3',
    '-webkit-box-orient: vertical',
    'overflow: hidden',
    'max-width: 100%',
    'margin-bottom: 4px',
  ].join('; ');
  bar.appendChild(descEl);
}

let metaEl = bar.querySelector('.' + metaEl_CLASS);
if (!metaEl) {
  metaEl = document.createElement('div');
  metaEl.className = metaEl_CLASS;
  metaEl.style.cssText = [
    'font-size: 11px',
    'font-weight: 500',
    'color: #e60023',
    'display: flex',
    'align-items: center',
    'gap: 4px',
    'margin-top: 2px',
  ].join('; ');
  bar.appendChild(metaEl);
}

// --- populate title: capitalise first 8 words ---
if (!displayText) return;
const words = displayText.split(' ');
const titleWords = words.slice(0, 8).join(' ');
const titleText = titleWords.charAt(0).toUpperCase() + titleWords.slice(1) + (words.length > 8 ? '…' : '');
titleEl.textContent = titleText;

// --- populate description (full text) ---
descEl.textContent = displayText;

// --- populate meta: pin ID as "Pin #XXXX" attribution ---
// Try to find a user link in the page that matches this pin's surrounding card
const boardLink = element.closest('[data-grid-item="true"]')
  ? element.closest('[data-grid-item="true"]').querySelector('a[href*="/pin/"]')
  : null;

// Show pin ID as unique identifier
metaEl.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="11" height="11" viewBox="0 0 24 24" fill="#e60023"><path d="M12 0C5.373 0 0 5.373 0 12c0 5.084 3.163 9.426 7.627 11.174-.105-.949-.2-2.405.042-3.441.218-.937 1.407-5.965 1.407-5.965s-.359-.719-.359-1.782c0-1.668.967-2.914 2.171-2.914 1.023 0 1.518.769 1.518 1.69 0 1.029-.655 2.568-.994 3.995-.283 1.194.599 2.169 1.777 2.169 2.133 0 3.772-2.249 3.772-5.495 0-2.873-2.064-4.882-5.012-4.882-3.414 0-5.418 2.561-5.418 5.207 0 1.031.397 2.138.893 2.738a.36.36 0 0 1 .083.345l-.333 1.36c-.053.22-.174.267-.402.161-1.499-.698-2.436-2.889-2.436-4.649 0-3.785 2.75-7.262 7.929-7.262 4.163 0 7.398 2.967 7.398 6.931 0 4.136-2.607 7.464-6.227 7.464-1.216 0-2.359-.632-2.75-1.378l-.748 2.853c-.271 1.043-1.002 2.35-1.492 3.146C9.57 23.812 10.763 24 12 24c6.627 0 12-5.373 12-12S18.627 0 12 0z"/></svg>'
  + ' pinterest.com/pin/' + pinId;
